import{M as a}from"./chunks/McpFeature.CtDtsj20.js";import{o as t,c as n,E as o,a3 as r}from"./chunks/framework.WFmvnizL.js";const h=JSON.parse(`{"title":"Nezha MCP — AI-Powered Server Management and Operations","description":"Connect Codex, OpenClaw, and Claude Code to Nezha MCP for natural-language fleet inspections, incident diagnosis, authorized commands, file management, and verified changes, with practical workflows and setup guidance.","frontmatter":{"title":"Nezha MCP — AI-Powered Server Management and Operations","description":"Connect Codex, OpenClaw, and Claude Code to Nezha MCP for natural-language fleet inspections, incident diagnosis, authorized commands, file management, and verified changes, with practical workflows and setup guidance.","outline":"deep","keywords":["Nezha MCP","AI operations","AI server management","Codex","OpenClaw","Claude Code","Model Context Protocol"],"faq":[{"question":"What is Nezha MCP?","answer":"Nezha MCP is a standard tool interface connecting AI assistants to servers. It provides server inventory, current state, remote commands, and file operations. AI interprets your goal; Nezha supplies the operational tools."},{"question":"Can I use it with Codex, OpenClaw, and Claude Code?","answer":"Clients supporting HTTP MCP and Bearer tokens can connect. Codex and Claude Code support remote MCP. OpenClaw needs an MCP client available to its current runtime or mcporter."},{"question":"Does Nezha include an AI model or chatbot?","answer":"No model is bundled. Nezha supplies monitoring and operations tools; your chosen AI client provides the model, conversation, reasoning, and workflow orchestration."},{"question":"Can MCP configure alerts, query historical metrics, or manage every Dashboard setting?","answer":"MCP provides server state, command, and file tools. Alert and task configuration, historical metrics, and other Dashboard settings require the Nezha admin UI or REST API."},{"question":"Can I automate incident response?","answer":"You can build workflows for diagnosis, authorized remediation, and verification. The client or external workflow provides scheduling, alert reception, and action confirmation. Nezha trigger tasks can execute reviewed scripts."},{"question":"Can data still reach an AI provider when Nezha is self-hosted?","answer":"Dashboard and server Agents can be self-hosted. With an external model, the client may send prompts, tool results, logs, or file contents to the model provider. Data handling depends on model deployment and the client's policies."}]},"headers":[],"relativePath":"en_US/guide/ai-operations.md","filePath":"en_US/guide/ai-operations.md","lastUpdated":1792674226000}`),s={name:"en_US/guide/ai-operations.md"},u=Object.assign(s,{setup(i){return(d,e)=>(t(),n("div",null,[o(a,{locale:"en"}),e[0]||(e[0]=r("",44))]))}});export{h as __pageData,u as default};
